    provisioning_status: 'pending' | 'awaiting_payment' | 'provisioning' | 'active' | 'failed';
    /**
     * URL to onboard the master tenant's payment method. Only present while `awaiting_payment`; `null` otherwise.
     */
    payment_setup_url: string | null;
    /**
     * Human-readable reason the provisioning failed. Only present when `provisioning_status` is `failed`; `null` otherwise.
     */
    failed_reason: string | null;
    /**
     * When provisioning started (ISO 8601), or `null` if not started yet.
     */
