/**
 * CreateWeeklyScheduleRequest
 */
export type CreateWeeklyScheduleRequest = {
    /**
     * Weekly schedule name.
     */
    name: string;
    /**
     * Schedule mode: `validated` (assumed fulfilled) or `real_clocking` (computed from real clock entries).
     */
    mode: 'validated' | 'real_clocking';
    /**
     * Weekly pattern: list of days with their time ranges.
     */
    week_pattern: Array<{
        /**
         * Day of the week in ISO 8601 format (1 Monday .. 7 Sunday).
         */
        day: number;
        /**
         * Time ranges for the day (empty = rest day).
         */
        ranges: Array<{
            /**
             * Range start time (HH:MM, 00:00-23:59).
             */
            start: string;
            /**
             * Range end time (HH:MM; 24:00 is allowed as end of workday).
             */
            end: string;
            flexible?: boolean;
            required_minutes?: number | null;
        }>;
    }>;
};

/**
 * CustomField
 *
 * A typed custom field as an ordered `{field, value}` pair. Distinct from `metadata` (a free key→value map): use `custom_fields` for structured, display-oriented integration metadata.
 */
export type CustomField = {
    /**
     * Field key (non-empty, ≤ 60 chars).
     */
    field: string;
    /**
     * Field value (≤ 500 chars).
     */
    value: string;
};

/**
 * CustomHeaders
 *
 * Custom HTTP headers (string → string) added to every delivery request for a webhook endpoint. Max 20 entries, each value ≤ 1024 chars. Header names are normalized to Title-Case. Reserved names (`Host`, `Content-Type`, `Factuarea-Signature`, `X-Forwarded-*`, …) are rejected. Empty object when none are set. Never put secrets here — values are returned verbatim by the API.
 */
export type CustomHeaders = {
    [key: string]: string;
};

/**
 * DailyPresence
 *
 * An office/remote presence declaration for the Control Horario (time tracking) module: an employee’s declared work location for a single day (one row per company + employee + day). Read-only over the public API — the declaration itself is made from the app (SPA-only).
 */
export type DailyPresence = {
    /**
     * Opaque identifier of the presence record, a UUID v7.
     */
    id: string;
    /**
     * Always `daily_presence`.
     */
    object: 'daily_presence';
    /**
     * UUID v7 of the employee the declaration belongs to.
     */
    employee_id: string;
    /**
     * Day of the declaration (`YYYY-MM-DD`).
     */
    date: string;
    /**
     * Declared work location: `office` or `remote`.
     */
    location: 'office' | 'remote';
    /**
     * Timestamp of the declaration (ISO 8601), or `null` when not retained.
     */
    declared_at: string | null;
};

/**
 * DayBalance
 *
 * The balance of a single day of the period for the Control Horario (time tracking) module: expected vs worked minutes, the resulting balance (worked − expected) and the day’s overtime minutes, plus the flags that explain why the expected minutes are zero (holiday, approved absence, rest day).
 */
export type DayBalance = {
    /**
     * Day of the breakdown (YYYY-MM-DD).
     */
    date: string;
    /**
     * Expected working minutes of the day derived from the schedule (0 on holidays, approved absences and rest days).
     */
    expected_minutes: number;
    /**
     * Worked minutes of the day.
     */
    worked_minutes: number;
    /**
     * Day balance in minutes (worked − expected); negative when the employee worked less than expected.
     */
    balance_minutes: number;
    /**
     * Overtime minutes of the day (worked above the configured threshold, with the tolerance applied).
     */
    overtime_minutes: number;
    /**
     * Whether the day is a public holiday for the employee.
     */
    is_holiday: boolean;
    /**
     * Whether the day is covered by an approved absence.
     */
    is_approved_absence: boolean;
    /**
     * Whether the day is a rest day (no shift in the schedule).
     */
    is_rest_day: boolean;
};

/**
 * DeactivateEmployeeRequest
 */
export type DeactivateEmployeeRequest = {
    /**
     * Effective termination date, in `Y-m-d`. Defaults to today when omitted.
     */
    termination_date?: string | null;
};

/**
 * DeclaracionResponsable
 *
 * The producer-level VeriFactu Declaración Responsable (SIF compliance declaration issued by the system producer, Factuarea). Global per `version`, read-only — not per-company.
 */
export type DeclaracionResponsable = {
    /**
     * UUID (v7) of the declaration.
     */
    id: string;
    object: 'verifactu_declaracion_responsable';
    /**
     * Version of the declaration (global key).
     */
    version: string;
    /**
     * Identifier of the invoicing software system (SIF).
     */
    system_id: string;
    /**
     * Name of the invoicing software system.
     */
    system_name: string;
    /**
     * Tax ID (NIF) of the SIF producer.
     */
    producer_tax_id: string;
    /**
     * Name of the SIF producer.
     */
    producer_name: string;
    /**
     * Indicates whether the system operates only in VeriFactu mode (tipo_uso = "S").
     */
    verifactu_only: boolean;
    /**
     * Indicator of multiple taxpayers.
     */
    multi_ot: boolean;
    /**
     * Date of the declaration.
     */
    declared_at: string;
    /**
     * Place where the declaration is signed.
     */
    signing_place: string;
    /**
     * SHA-256 hash of the declaration content for integrity verification (the full content is not exposed).
     */
    content_hash: string;
    created_at: string;
};

/**
 * DeliveryNote
 *
 * A delivery note tracking goods delivered to a customer. The delivery address fields, `transport_details` and `reference_number` are both accepted on write and returned here; `delivery_city`, `delivery_province` and `delivery_postal_code` are also filterable on `GET /v1/delivery_notes`. Empty strings are normalized to `null`.
 */
export type DeliveryNote = {
    id: string;
    object: 'delivery_note';
    number: string;
    series: SeriesRef;
    client: ClientRef;
    /**
     * Delivery note lifecycle status exposed by the public API: `draft` (created, editable), `sent` (goods marked as delivered, no signature recorded yet), `signed` (delivered AND a recipient signature has been recorded), `invoiced` (converted into an invoice, terminal), `cancelled` (terminal). Note: the internal `delivered` state is surfaced as `sent` (without signature) or `signed` (with signature) — there is no `delivered` value in the public API. Recording a signature on a `sent` note moves it to `signed` (it does not introduce a brand-new lifecycle stage; the signature presence is the only difference).
     */
    status: 'draft' | 'sent' | 'signed' | 'invoiced' | 'cancelled';
    /**
     * UUID of the price list selected for this document.
     */
    price_list_id: string | null;
    /**
     * Price-list name snapshot frozen on the document.
     */
    price_list_name: string | null;
    /**
     * Status of the PHYSICAL axis of the delivery note — where the goods are — which is ORTHOGONAL to the `status` above: no transition of this axis changes the commercial status and no commercial transition changes this one. It is NEVER `null`: its column is `NOT NULL DEFAULT pending`, so a note that never entered picking publishes the initial status of the catalog. Its closed catalog is published by its own operation (`GET .../delivery-notes/fulfilment-statuses`) and shares no value with the catalog of delivery note statuses.
     */
    fulfilment_status: 'pending' | 'picking' | 'prepared' | 'handed_over' | 'in_transit' | 'delivered' | 'failed';
    /**
     * Label of the physical status in Spanish, ready to display, from the same single source as the catalog. Never `null`, for the same reason as the status itself.
     */
    fulfilment_status_label: string;
    /**
     * The carrier of the MASTER referenced by this delivery note, or `null` when none is referenced — the key always travels, like `driver`, `tracking` and `received_by`. It does NOT replace `tracking.carrier`: that one is the free text that was typed before the master existed and it travels alongside the reference, which is what makes the migration to the master reversible.
     */
    carrier: {
        /**
         * Opaque identifier of the carrier, a UUID v7. The internal foreign key of the delivery note is never published.
         */
        id: string | null;
        /**
         * Name of the carrier, ready to display.
         */
        name: string | null;
    } | null;
    /**
     * Date the goods are EXPECTED to be delivered (`YYYY-MM-DD`, a pure date and not a timestamp). It is a forecast of the physical axis and a DIFFERENT thing from `delivery_date`, which is the date of the document. `null` when there is none.
     */
    expected_delivery_date: string | null;
    /**
     * Free-text reference of the packages the carrier gave for this shipment (a consignment note, a manifest). `null` when there is none; an empty string is normalised to `null`.
     */
    packages_reference: string | null;
    /**
     * Tracking URL, DERIVED on every read from the template of the carrier and the tracking number, with the number URL-escaped, and NEVER stored: changing the template of a carrier changes the published URL of all of its delivery notes without rewriting a single row. `null` when the carrier has no template or the note has no tracking number — never an empty string and never a broken link. Note the deliberate difference with the shipment sub-resource, where this same value is published as an ABSENT key instead of a null: here the six keys of the axis always travel so that the document has one single shape.
     */
    tracking_url: string | null;
    issued_on: string | null;
    delivery_date: string | null;
    /**
     * Street of the delivery address recorded on the delivery note. `null` when not set.
     */
    delivery_address: string | null;
    /**
     * Town or city of the delivery address recorded on the delivery note. Filterable via `?delivery_city=` (also `[in]` and `[contains]`). `null` when not set.
     */
    delivery_city: string | null;
    /**
     * Postal code of the delivery address recorded on the delivery note. Filterable via `?delivery_postal_code=`; the first two digits identify the Spanish province. `null` when not set.
     */
    delivery_postal_code: string | null;
    /**
     * Province of the delivery address recorded on the delivery note. Filterable via `?delivery_province=` (also `[in]` and `[contains]`). `null` when not set.
     */
    delivery_province: string | null;
    /**
     * Country of the delivery address recorded on the delivery note. Free text, not an ISO code. `null` when not set.
     */
    delivery_country: string | null;
    signed_at: string | null;
    signed_by: string | null;
    signature_image_url: string | null;
    /**
     * Free-text transport details of the delivery. `null` when not set.
     */
    transport_details: string | null;
    /**
     * License plate of the delivery vehicle.
     */
    vehicle_plate: string | null;
    /**
     * Delivery driver data. `null` when no sub-field is provided.
     */
    driver: {
        /**
         * Driver name.
         */
        name: string | null;
        /**
         * Driver tax ID (NIF/CIF/NIE).
         */
        tax_id: string | null;
    } | null;
    /**
     * Shipment tracking data. `null` when no sub-field is provided.
     */
    tracking: {
        /**
         * Shipment tracking number.
         */
        number: string | null;
        /**
         * Transport / courier company.
         */
        carrier: string | null;
    } | null;
    /**
     * Goods recipient data. `null` when no sub-field is provided.
     */
    received_by: {
        /**
         * Name of the person who received the goods.
         */
        name: string | null;
        /**
         * Recipient tax ID (NIF/CIF/NIE).
         */
        tax_id: string | null;
    } | null;
    /**
     * Additional emails for delivery note dispatch (administration, accounting). Maximum 5. Empty `[]` when there are none.
     */
    billing_emails: Array<string>;
    subtotal: string;
    /**
     * NET aggregate of the header taxes: `total_vat + total_surcharge − total_retention`. It is the amount that, added to `subtotal`, yields `total` (`total === subtotal + taxes_total`), so it must NOT be combined with `total_retention`: subtracting the withholding again on top of the aggregate produces a false total (4,320.00 + 259.20 − 648.00 = 3,931.20 against a real total of 4,579.20). It is NOT the VAT figure of the Spanish Modelo 303 — read `total_vat` for that. Beware that on a purchase invoice the same field name carries a DIFFERENT meaning (VAT only), which is why the identity that holds across all five document families is the explicit one: `total === subtotal + total_vat + total_surcharge − total_retention`.
     */
    taxes_total: string;
    /**
     * Output VAT (IVA repercutido) accrued by the document: sum of the VAT of its lines. This is the figure a Spanish Modelo 303 declares, and it is NOT recoverable from `taxes_total`, which nets the withholding out.
     */
    total_vat: string;
    /**
     * Withholding (retención de IRPF) applied to the document: sum of the withholding of its lines, as a POSITIVE amount that SUBTRACTS from the total. This is the figure a Spanish Modelo 130/111 declares. It is ALREADY netted out inside `taxes_total`, so do not subtract it again.
     */
    total_retention: string;
    /**
     * Equivalence surcharge (recargo de equivalencia) of the document: sum of the surcharge of its lines. It ADDS to the total exactly like VAT does, and is ALREADY included inside `taxes_total`.
     */
    total_surcharge: string;
    /**
     * Total of the document. Two equivalent ways to reconstruct it from the published amounts, and only these two: the EXPLICIT one, identical in the five document families - `total = subtotal + total_vat + total_surcharge - total_retention` - or the AGGREGATE one, specific to the sales-side families - `total = subtotal + taxes_total`. NEVER reconstruct it as `subtotal + taxes_total - total_retention`: `taxes_total` ALREADY has the withholding netted out, so that combination subtracts it twice and yields a false total (4,320.00 + 259.20 - 648.00 = 3,931.20 against a real 4,579.20).
     */
    total: string;
    currency: string;
    notes: string | null;
    /**
     * External integration key (ERP/CRM/e-commerce) mapping this document to a record in a third-party system. Free-format, unique per company, filterable via `?external_id=`. `null` when not set. Persistent synchronization key, independent of the request-level `Idempotency-Key`.
     */
    external_id: string | null;
    /**
     * Commercial reference of the delivery note — usually the client's purchase order number, which an ERP uses to reconcile its orders against deliveries. `null` when not set.
     */
    reference_number: string | null;
    lines: Array<DeliveryNoteLine>;
    metadata: Metadata;
    /**
     * Free classification tags (lowercase slugs `[a-z0-9-]`, ≤ 40 chars each, ≤ 30 tags). Filterable via `?tags[in]=tag1,tag2` (JSON_CONTAINS, OR semantics). Empty `[]` when there are none.
     */
    tags: Array<string>;
    /**
     * Ordered list of typed custom fields `[{field, value}]` (≤ 50). Distinct from `metadata` (a free key→value map): use `custom_fields` for structured, display-oriented integration metadata. Empty `[]` when there are none.
     */
    custom_fields: Array<CustomField>;
    /**
     * UUID (v7) of the invoice this delivery note was converted into.
     */
    converted_to_id: string | null;
    created_at: string | null;
    updated_at: string | null;
};

/**
 * DeliveryNoteLine
 *
 * A line item on a delivery note.
 */
export type DeliveryNoteLine = {
    object: 'delivery_note_line';
    description: string | null;
    /**
     * Optional secondary description rendered below the line concept on document PDFs.
     */
    additional_description: string | null;
    product: ProductRef | null;
    quantity: number;
    unit_price: string;
    tax_rate: number;
    /**
     * IRPF withholding percentage applied to the line (0–100). Default 0. Its amount is already aggregated into `taxes`.
     */
    retention_rate: number;
    /**
     * Equivalence surcharge (recargo de equivalencia) percentage applied to the line (0–100). Default 0. Its amount is already aggregated into `taxes`.
     */
    surcharge_rate: number;
    discount_percent: number;
    subtotal: string;
    taxes: string;
    total: string;
    /**
     * Indirect tax regime of the line: the per-document override (`iva`/`igic`/`ipsi`) when the user set it (precedence override>zone), otherwise `null` (derived from the establishment AEAT zone). Writable per-document input on create/update; the document must be homogeneous (a single non-null regime across all lines, 422 otherwise).
     */
    indirect_tax_regime?: 'iva' | 'igic' | 'ipsi' | null;
    variant: {
        id: string;
        name: string | null;
    } | null;
    presentation: {
        id: string;
        name: string | null;
        mode: string | null;
    } | null;
    item_kind: string | null;
    commercial_unit_code: string | null;
    base_unit_code: string | null;
    conversion_factor: string | null;
    base_quantity: string | null;
    price_list_id: string | null;
    price_list_name: string | null;
    price_source: string | null;
    price_unit_code: string | null;
    /**
     * Commercial combination frozen on the line, or `null` when the line was not sold or bought through one (legacy product, manual line).
     */
    configuration: {
        id: string;
        name: string | null;
        signature: string | null;
    } | null;
    /**
     * Configurable options frozen on the line, in printing order. Always an array, `[]` included.
     */
    options: Array<{
        group: {
            id: string;
            name: string | null;
        };
        value: {
            id: string;
            name: string | null;
        };
        /**
         * Adjustment of the chosen value per commercial unit. `null` means the value does not change the price — NOT the same as adjusting by `0`.
         */
        price_adjustment: string | null;
        /**
         * Whether that amount was actually ADDED to the unit price. `false` when an exact price (price-list entry, combination price or a manually typed unit price) already absorbed it.
         */
        applied: boolean;
    }>;
    /**
     * Monetary semantics of the resolved price: `per_base_unit` (product/variant own price, converted once by the presentation factor) or `per_commercial_unit` (presentation, combination or price-list entry, never converted). `null` on a line with no catalog price context.
     */
    price_semantics: 'per_base_unit' | 'per_commercial_unit' | null;
    /**
     * Sum of the adjustments of the chosen option values, as a decimal string. Informational when an exact price already absorbed them.
     */
    price_adjustment_total: string | null;
    /**
     * TRI-STATE, and `null` is NOT `false`. `true`: the resolved price already includes the option adjustments. `false`: they were added on top. `null`: it could not be determined — the assembler refuses such a line with 422 rather than risking charging the adjustments twice, so `null` only ever reaches a reader on a legacy line with no configurable options at all.
     */
    option_adjustments_absorbed: boolean | null;
};

/**
 * DeliveryNotePickingList
 *
 * The picking list of a delivery note: the SNAPSHOT of its live lines at the moment the list was opened, with what has to be picked out of the warehouse. It has no identity of its own — it is addressed through its delivery note — and opening it again REPLACES it, losing the previous picking work, which is why the opening is published as irreversible.
 */
export type DeliveryNotePickingList = {
    /**
     * Opaque identifier of the delivery note the list belongs to. It is the identity of the list: there is at most one picking list per delivery note.
     */
    delivery_note_id: string;
    /**
     * Always `delivery_note_picking_list`.
     */
    object: 'delivery_note_picking_list';
    /**
     * Readable number of the delivery note, so a warehouse screen does not need a second read to title the list. `null` when the note has not been numbered yet.
     */
    delivery_note_number: string | null;
    /**
     * Status of the PHYSICAL axis of the delivery note. It is orthogonal to the commercial status of the note: no transition of this axis changes that one, and no commercial transition changes this one.
     */
    fulfilment_status: 'pending' | 'picking' | 'prepared' | 'handed_over' | 'in_transit' | 'delivered' | 'failed';
    /**
     * Label of the physical status in Spanish, from the same single source as the catalog.
     */
    fulfilment_status_label: string;
    /**
     * Whether the list is STALE: the lines of the delivery note changed after the list was opened, so the snapshot no longer matches the document. It is published explicitly and never fixed silently. While it is `true`, picking a line and moving the axis to `prepared` are rejected as business rule violations and the message says the remedy: reopen the picking. A stale list is NEVER deleted automatically — the work of the warehouse is kept until somebody decides to reopen it.
     */
    is_stale: boolean;
    /**
     * Opaque identifier of the warehouse the goods come out of. This key is ABSENT — not `null` — when the delivery note does not pin one. It travels as an OPAQUE identifier without its name: resolving the name would cross into another bounded context just for presentation, and the warehouse has its own published resource.
     */
    warehouse_id?: string;
    /**
     * Opaque identifier of the sales order the delivery note came from. This key is ABSENT when the note has no order behind it. Like the warehouse, it travels without its number or its name.
     */
    sales_order_id?: string;
    /**
     * Number of lines in the list. It is a COUNT and not an identifier.
     */
    line_count: number;
    /**
     * Number of lines that are NOT fully picked yet. It is DERIVED by the read model and never stored, so the two representations of the list cannot disagree.
     */
    pending_line_count: number;
    /**
     * Lines of the picking list, each one with its own public identifier. They come with the list so a client can pick them without an extra read.
     */
    lines: Array<PickingListLine>;
};

/**
 * DeliveryNoteShipment
 *
 * The SHIPMENT of a delivery note: the carrier, the tracking and the packages the goods travel in. There is no shipment table — the shipment is the view of the transport columns of the delivery note plus its packages — so it has no identifier of its own and it is addressed through its delivery note. Its partial update touches ONLY what the body carries: an absent key is not touched, and "absent" and "set to null" are told apart explicitly and never by an empty string.
 */
export type DeliveryNoteShipment = {
    /**
     * Opaque identifier of the delivery note. It is the identity of the shipment: there is exactly one shipment per delivery note.
     */
    delivery_note_id: string;
    /**
     * Always `delivery_note_shipment`.
     */
    object: 'delivery_note_shipment';
    /**
     * Readable number of the delivery note. `null` when the note has not been numbered yet.
     */
    delivery_note_number: string | null;
    /**
     * Status of the physical axis of the delivery note, so a client reading the shipment knows where the goods are without a second call.
     */
    fulfilment_status: 'pending' | 'picking' | 'prepared' | 'handed_over' | 'in_transit' | 'delivered' | 'failed';
    /**
     * Label of the physical status in Spanish.
     */
    fulfilment_status_label: string;
    /**
     * Opaque identifier of the carrier of the MASTER. This key is ABSENT — not `null` — when the shipment has no carrier referenced. It is absent under exactly the same condition as `carrier_name`: either both travel or neither does.
     */
    carrier_id?: string;
    /**
     * Name of the referenced carrier, so a shipment screen does not need a second read. ABSENT under the same condition as `carrier_id`.
     */
    carrier_name?: string;
    /**
     * FREE TEXT of the transport company, which is what was typed before the carrier master existed. It travels ALONGSIDE the reference and it is not redundancy: it is what makes the migration to the master reversible, because assigning a carrier fills the reference and never touches this text. `null` when there is none; unlike the two keys above, this one always travels.
     */
    carrier_company: string | null;
    /**
     * Tracking number of the shipment, or `null`. It is READ here but NOT written by the partial update of the shipment: it has a single write path, the update of the delivery note itself, so that there is one place where the number of a document changes.
     */
    tracking_number: string | null;
    /**
     * Tracking URL, DERIVED on every read from the template of the carrier and the tracking number, with the number URL-escaped. It is NEVER stored: changing the template of a carrier changes the published URL of all of its shipments without rewriting a single row. This key is ABSENT — never an empty string and never a broken link — when the carrier has no template or the shipment has no number.
     */
    tracking_url?: string;
    /**
     * Date the goods are EXPECTED to be delivered (`YYYY-MM-DD`, a pure date and not a timestamp). It is a forecast and a different thing from the delivery date of the document. `null` when there is none. It is also a sort field of the picking queue.
     */
    expected_delivery_date: string | null;
    /**
     * Free-text reference of the packages the carrier gave for this shipment (a consignment note, a manifest). `null` when there is none; an empty string is normalised to `null`.
     */
    packages_reference: string | null;
    /**
     * Packages of the shipment, EMBEDDED and NOT paginated: `total` is a count of packages and not a page size, and there is no cursor. The same collection is served on its own by `GET .../delivery-notes/{delivery_note}/packages`, with the same three keys.
     */
    packages: {
        /**
         * The packages, in their deterministic position order. An empty list when there are none.
         */
        data: Array<ShipmentPackage>;
        /**
         * Number of packages of the shipment.
         */
        total: number;
        /**
         * Total weight of the shipment in kilograms, as a decimal string with two decimal places. It is the SUM of the weight of the packages, computed by the domain on every read and NOT read from any stored column: a stored total and a computed sum diverge at the first edit of a package. A package with no weight adds nothing, and a shipment with no packages publishes `"0.00"`.
         */
        total_weight_kg: string;
    };
};

/**
 * DeliveryNoteStats
 *
 * Resumen agregado de los albaranes de la empresa autenticada: total, importe acumulado, desglose por estado interno, pendientes de firma y convertidos a factura este mes. Devuelto por `GET /v1/delivery_notes/stats`.
 */
export type DeliveryNoteStats = {
    /**
     * Total number of recorded delivery notes.
     */
    total_count: number;
    /**
     * Aggregate amount of the delivery notes (EUR).
     */
    total_amount: number;
    /**
     * Breakdown by internal delivery note state. The key is the internal state (`draft`, `delivered`, `invoiced`, `cancelled`); the value is an object with `status`, `count` and `total` (accumulated amount in EUR). States with no delivery notes do not appear.
     */
    by_status: {
        [key: string]: {
            /**
             * Internal state of the delivery note.
             */
            status: string;
            /**
             * Number of delivery notes in that state.
             */
            count: number;
            /**
             * Aggregate amount of the delivery notes in that status (EUR).
             */
            total: number;
        };
    };
    /**
     * Delivered delivery notes (`delivered`) that do not yet have a recorded signature.
     */
    pending_signature: number;
    /**
     * Delivery notes converted to an invoice (`invoiced`) during the current month.
     */
    converted_this_month: number;
};

/**
 * DeliveryNoteStatusItem
 *
 * Delivery note status from the closed catalog with its label and color for UI.
 */
export type DeliveryNoteStatusItem = {
    /**
     * Internal status identifier.
     */
    value: 'draft' | 'delivered' | 'invoiced' | 'cancelled';
    /**
     * Human-readable status label (Spanish).
     */
    label: string;
    /**
     * Suggested color for rendering the status in the UI.
     */
    color: string;
};

/**
 * DryRunAutomationRuleV1Request
 */
export type DryRunAutomationRuleV1Request = {
    /**
     * Sample event type to test the rule with, in `resource.action` form (for example `invoice.paid`). Must belong to the catalog visible to the company.
     */
    event_type: string;
    /**
     * The `data.object` of the sample event: an object with named keys, never a list.
     */
    event_payload: {
        [key: string]: unknown;
    };
    /**
     * ID (UUID v7) of the sample resource to predict against. Required for rules whose actions operate on a document.
     */
    event_aggregate_id?: string | null;
};

/**
 * EmailDelivery
 *
 * One email your company sent through the platform (an invoice, a quote, a payment reminder…). Read-only and scoped to your own company. Internal implementation details — the mailable class, the queue job id, the user id and the raw metadata — are never exposed.
 */
export type EmailDelivery = {
    /**
     * UUID v7 of the send. Use it in `GET /v1/emails/{email}`.
     */
    id: string;
    /**
     * Always `email_delivery`.
     */
    object: 'email_delivery';
    /**
     * Address the message was sent to.
     */
    recipient_email: string;
    /**
     * Addresses in copy. Empty array when there were none.
     */
    cc: Array<string>;
    /**
     * Addresses in blind copy. Empty array when there were none.
     */
    bcc: Array<string>;
    /**
     * Subject line of the message.
     */
    subject: string;
    /**
     * Status of the send. It describes the hand-off to the OUTGOING SMTP SERVER, NOT real delivery to the recipient's mailbox: `queued` (accepted, waiting for the worker), `sending` (being handed off), `sent` (the outgoing mail server accepted the message) and `failed` (every attempt failed). A `sent` message can still bounce or land in spam afterwards without the platform finding out. There are deliberately no `delivered`, `bounced` or `opened` values: observing them would require a mail provider with delivery webhooks, which is out of scope.
     */
    status: 'queued' | 'sending' | 'sent' | 'failed';
    /**
     * Number of hand-off attempts made for this message.
     */
    attempts: number;
    /**
     * Error reported by the outgoing mail server on the last failed attempt, or `null` when there was none.
     */
    error_message: string | null;
    /**
     * When the outgoing mail server accepted the message (ISO 8601), or `null` if it never did. It marks the hand-off, not a confirmed delivery or a read.
     */
    sent_at: string | null;
    /**
     * When the last attempt failed (ISO 8601), or `null` when none failed.
     */
    failed_at: string | null;
    /**
     * When the send was registered (ISO 8601).
     */
    created_at: string | null;
    /**
     * Type of the document the email was sent for, or `null` for non-document emails (test messages, account emails).
     */
    related_entity_type: 'invoice' | 'quote' | 'proforma' | 'delivery_note' | 'purchase_invoice' | 'recurring_invoice' | null;
    /**
     * UUID v7 of the related document, or `null` for non-document emails and for older rows recorded before the sender stored it.
     */
    related_entity_id: string | null;
};

/**
 * EmailDeliveryIndicator
 *
 * Aggregated email summary for ONE related document. Only documents that have at least one email produce an entry.
 */
export type EmailDeliveryIndicator = {
    /**
     * UUID v7 of the document, exactly as you sent it in `related_entity_ids`. Match the results back by this field, never by position.
     */
    related_entity_id: string;
    /**
     * Document type RESOLVED for this id. It is always reported, even when you did not send `related_entity_type`, so a batch can mix types safely.
     */
    related_entity_type: 'invoice' | 'quote' | 'proforma' | 'delivery_note' | 'purchase_invoice' | 'recurring_invoice';
    /**
     * Always `email_delivery_indicator`.
     */
    object: 'email_delivery_indicator';
    /**
     * Number of emails registered for this document.
     */
    total: number;
    /**
     * Status of the most recent email of this document. Status of the send. It describes the hand-off to the OUTGOING SMTP SERVER, NOT real delivery to the recipient's mailbox: `queued` (accepted, waiting for the worker), `sending` (being handed off), `sent` (the outgoing mail server accepted the message) and `failed` (every attempt failed). A `sent` message can still bounce or land in spam afterwards without the platform finding out. There are deliberately no `delivered`, `bounced` or `opened` values: observing them would require a mail provider with delivery webhooks, which is out of scope.
     */
    last_status: 'queued' | 'sending' | 'sent' | 'failed';
    /**
     * Latest time something left for the outgoing mail server (ISO 8601), or `null` if nothing ever did. It is the MAXIMUM across the document's emails, so it can be non-null while `last_status` is `failed`: the last attempt failed, an earlier one went out.
     */
    last_sent_at: string | null;
    /**
     * Highest number of attempts among the emails of this document — the maximum, NOT their sum.
     */
    attempts: number;
    /**
     * How many emails of this document ended in `failed`.
     */
    failed_count: number;
};

/**
 * EmailDeliveryIndicators
 *
 * Email summary of a batch of documents (`{ data }`). It does NOT paginate: you asked for a bounded batch (up to 100 ids) and you get one entry per document that HAS emails. Documents without any email, and ids that do not belong to a document of your company, are OMITTED — never returned with zeros — so `data` can be shorter than the batch you sent, or empty.
 */
export type EmailDeliveryIndicators = {
    /**
     * One entry per requested document that has at least one email.
     */
    data: Array<EmailDeliveryIndicator>;
};

/**
 * EmailDeliveryList
 *
 * Cursor-paginated page of sent emails (`{ data, has_more, next_cursor }`), most recent first.
 */
export type EmailDeliveryList = {
    /**
     * Page of sent emails, newest first.
     */
    data: Array<EmailDelivery>;
    /**
     * `true` when more emails exist beyond this page.
     */
    has_more: boolean;
    /**
     * Opaque cursor to pass as `starting_after` for the next page, or `null` when `has_more` is `false`. Unlike the rest of the v1 listings it is a numeric string, not a UUID v7 — treat it as opaque and reuse it verbatim.
     */
    next_cursor: string | null;
};

/**
 * Employee
 *
 * An employee of your company. Active employees count towards the seat billing of the workforce module; deactivated ones are preserved with their termination date.
 */
export type Employee = {
    /**
     * Opaque identifier of the employee, a UUID v7 (e.g. `01931b3e-7c4a-7f2e-9a8b-3c5d6e7f8a9b`).
     */
    id: string;
    /**
     * Always `employee`.
     */
    object: 'employee';
    /**
     * Given name of the employee.
     */
    first_name: string;
    /**
     * Family name of the employee.
     */
    last_name: string;
    /**
     * Contact email of the employee.
     */
    email: string;
    /**
     * Spanish fiscal identifier (NIF/NIE) of the employee, or `null` when unknown. Not a foreign key.
     */
    tax_id: string | null;
    /**
     * Role or position of the employee, or `null` when unset.
     */
    job_title: string | null;
    /**
     * Working-hours arrangement: `full_time` or `part_time`.
     */
    employment_type: 'full_time' | 'part_time';
    /**
     * Weekly contracted hours (e.g. `40` for a full-time schedule).
     */
    contract_hours: number;
    /**
     * Calendar date the employee was hired, in `Y-m-d`.
     */
    hire_date: string;
    /**
     * Calendar date the employee was deactivated, in `Y-m-d`; `null` while active.
     */
    termination_date: string | null;
    /**
     * Spanish autonomous community (comunidad autónoma) the employee is assigned to, as its two-letter code.
     */
    ccaa: 'AN' | 'AR' | 'AS' | 'IB' | 'CN' | 'CB' | 'CL' | 'CM' | 'CT' | 'VC' | 'EX' | 'GA' | 'MD' | 'MC' | 'NC' | 'PV' | 'RI' | 'CE' | 'ML';
    /**
     * Lifecycle status: `active` (in the workforce) or `inactive` (deactivated).
     */
    status: 'active' | 'inactive';
    /**
     * External integration key (ERP/CRM/HR system) mapping this employee to a record in a third-party system. Free-format, unique per company, distinct from the fiscal `tax_id`.
     */
    external_id?: string | null;
    metadata: Metadata;
    /**
     * UUID v7 of the portal user linked to this employee, or `null` when no linkage exists yet.
     */
    user_id: string | null;
    /**
     * Creation timestamp (ISO 8601).
     */
    created_at: string | null;
    /**
     * Last-update timestamp (ISO 8601).
     */
    updated_at: string | null;
};

/**
 * EmployeeInvitation
 *
 * An invitation for a person to join your company as an employee (Control Horario portal). Reuses the invitation subsystem with role `employee`; it does not consume the plan `users` seat limit.
 */
export type EmployeeInvitation = {
    /**
     * Opaque identifier of the invitation, a UUID v7 (e.g. `01931b3e-7c4a-7f2e-9a8b-3c5d6e7f8a9b`).
     */
    id: string;
    /**
     * Always `employee_invitation`.
     */
    object: 'employee_invitation';
    /**
     * Email address the invitation was sent to.
     */
    email: string;
    /**
     * Always `employee` for this surface.
     */
    role: 'employee';
    /**
     * Lifecycle status of the invitation: `pending` (awaiting acceptance), `accepted`, `canceled` or `expired`.
     */
    status: 'pending' | 'accepted' | 'canceled' | 'expired';
    /**
     * Expiry timestamp of the invitation link (ISO 8601), or `null`.
     */
    expires_at: string | null;
    /**
     * Creation timestamp (ISO 8601).
     */
    created_at: string | null;
};

/**
 * EmployeePresence
 *
 * Live presence of an employee for the Control Horario (time tracking) module: a read-only projection derived from the immutable time record ledger and the employee’s planned schedule. `work_state` is the derived workday state; `is_late` is true when the first clock-in of the day happened after the planned start time. A computed resource with no entity identity of its own: its `id` is the UUID v7 of the employee, never a presence record id.
 */
export type EmployeePresence = {
    /**
     * UUID v7 of the employee this presence belongs to (the resource has no id of its own).
     */
    id: string;
    /**
     * Always `employee_presence`.
     */
    object: 'employee_presence';
    /**
     * Display name of the employee.
     */
    display_name: string;
    /**
     * Derived workday state from the ledger: `working`, `paused`, `finished` (clocked out) or `away` (no open workday).
     */
    work_state: 'working' | 'paused' | 'finished' | 'away';
    /**
     * Start of the current open segment (ISO 8601), or `null` when there is no open workday.
     */
    since: string | null;
    /**
     * First clock-in of the day (ISO 8601), or `null` when the employee has not clocked in today.
     */
    first_clock_in_at: string | null;
    /**
     * true when the employee clocked in after their planned start time.
     */
    is_late: boolean;
    /**
     * Planned start time of the day (ISO 8601), or `null` on a rest day / when no schedule applies.
     */
    planned_start_at: string | null;
    /**
     * Declared work location for today: `office`, `remote`, or `null` when not declared.
     */
    location: 'office' | 'remote' | null;
    /**
     * true when the employee has declared a work location today (distinguishes "office not declared" from "no data").
     */
    location_declared: boolean;
};

/**
 * EmployeeSchedule
 *
 * The work schedule currently in effect for an employee on a given date, resolved from the employee’s open assignment. `id` is the UUID v7 of the underlying work schedule (not of the assignment).
 */
export type EmployeeSchedule = {
    /**
     * UUID v7 of the work schedule currently in effect for the employee.
     */
    id: string;
    /**
     * Always `employee_work_schedule`.
     */
    object: 'employee_work_schedule';
    /**
     * Human-readable name of the schedule.
     */
    name: string;
    /**
     * Mode of the schedule: `validated` or `real_clocking`.
     */
    mode: 'validated' | 'real_clocking';
    /**
     * Weekly pattern: one entry per configured weekday with its ordered, non-overlapping time ranges. A weekday absent from the list (or with an empty `ranges`) is a rest day.
     */
    week_pattern: Array<{
        /**
         * ISO 8601 weekday (1 = Monday … 7 = Sunday).
         */
        day: number;
        /**
         * Ordered, non-overlapping time ranges worked that day (empty = rest day).
         */
        ranges: Array<{
            /**
             * Range start time (HH:MM, 24h).
             */
            start: string;
            /**
             * Range end time (HH:MM, 24h).
             */
            end: string;
        }>;
    }>;
    /**
     * Total weekly hours derived from the pattern.
     */
    weekly_hours: number;
    /**
     * Date the schedule became effective for the employee, in `Y-m-d`.
     */
    effective_from: string;
};

/**
 * EmployeeSeatBillingStatus
 *
 * Billing status of the per-employee add-on for your company (Control Horario). Whether the dedicated `employee-seats` subscription is active, how many seats are billed, how many employees are active and the recurring per-seat cost. Amounts are in minor currency units (cents) and are null when the cost is not resolvable (not subscribed, no active plan, enterprise outside Stripe, sandbox) — never a misleading 0. Employees never count towards the plan `users` seat limit. Read `subscribed` together with `seats_billable` to tell a legitimate no-charge state apart from a billing anomaly.
 */
export type EmployeeSeatBillingStatus = {
    /**
     * Stripe-like discriminator. Always `employee_seat_billing_status` for this resource.
     */
    object: 'employee_seat_billing_status';
    /**
     * true when the company has the per-employee add-on subscribed (`employee-seats` subscription active).
     */
    subscribed: boolean;
    /**
     * Number of BILLED seats: while subscribed it follows the number of active employees; 0 when not subscribed.
     */
    quantity: number;
    /**
     * Real number of `active` employees of the company. When not subscribed it reveals how many seats an opt-in would bill; when subscribed it matches `quantity`.
     */
    active_employees: number;
    /**
     * Taxable base of one seat per billing cycle, in cents, or null when not resolvable.
     */
    unit_amount: number | null;
    /**
     * Applied VAT rate (e.g. 21), or null when not resolved.
     */
    tax_rate: number | null;
    /**
     * VAT amount of one seat, in cents, or null.
     */
    tax_amount: number | null;
    /**
     * Base + VAT of one seat, in cents, or null.
     */
    total_per_seat: number | null;
    /**
     * Projected recurring total (`total_per_seat` × `quantity`), in cents. Null when VAT is not resolved.
     */
    recurring_total: number | null;
    /**
     * ISO 4217 currency code (uppercase).
     */
    currency: string;
    /**
     * The seat is always billed monthly, regardless of the plan interval; null when not subscribed.
     */
    billing_interval: 'month' | null;
    /**
     * End of the current covered period of the seat subscription (ISO 8601), or null.
     */
    next_invoice_at: string | null;
    /**
     * true when the company has no active paid plan, so the seat cost cannot be resolved.
     */
    requires_active_plan: boolean;
    /**
     * true when your company MUST be paying per seat (live paid plan), regardless of whether the `employee-seats` subscription exists — it is independent of `subscribed`. Combine both: `subscribed: true` means seats are being billed normally; `subscribed: false` with `seats_billable: true` and `active_employees > 0` is a BILLING ANOMALY (active employees with no seat billed) that your provider must settle; `seats_billable: false` is a legitimate no-charge state (enterprise by contract, trial or sandbox).
     */
    seats_billable: boolean;
};

/**
 * EmployeeSeatChargePreview
 *
 * Preview of the prorated per-seat charge for activating or hiring employees, computed from the Stripe upcoming invoice without charging. The exclusive reason flags for a 0 amount, by precedence: `already_covered` > `requires_active_plan` > `included_in_trial`. At most one is true. `requires_payment_method` is NOT a 0-amount branch: it flags an obstacle on a REAL amount. Read `seats_billable` before promising a charge: when false the operation never bills (enterprise by contract, trial, sandbox or live mode off) even though the amount is computed. Amounts are in minor currency units (cents).
 */
export type EmployeeSeatChargePreview = {
    /**
     * Stripe-like discriminator. Always `employee_seat_charge_preview` for this resource.
     */
    object: 'employee_seat_charge_preview';
    /**
     * Taxable base of the proration (without VAT), in cents.
     */
    amount: number;
    /**
     * VAT amount of the proration, in cents.
     */
    tax_amount: number;
    /**
     * Total actually charged (`amount + tax_amount`), in cents.
     */
    total: number;
    /**
     * Applied VAT rate (e.g. 21), or null when Stripe Tax did not resolve it (then `tax_amount` is 0 and `total` = `amount`).
     */
    tax_rate: number | null;
    /**
     * ISO 4217 currency code (uppercase).
     */
    currency: string;
    /**
     * End of the current period of the seat subscription (ISO 8601), never today; null when not resolvable.
     */
    next_invoice_date: string | null;
    /**
     * true when the company operates in live mode with no payment method on file. This does NOT zero the amount: the proration is still computed (previewing it needs no card), so you can show what the operation will cost before asking for the card. Configure the payment method to proceed.
     */
    requires_payment_method: boolean;
    /**
     * true when the company has no active paid plan (amount is 0).
     */
    requires_active_plan: boolean;
    /**
     * true when the company is on trial, so the activation is free (amount is 0) until the trial converts to a paid plan.
     */
    included_in_trial: boolean;
    /**
     * true when every employee to activate is still covered this period (free reactivation, amount is 0).
     */
    already_covered: boolean;
    /**
     * true when the activation creates the FIRST seat subscription of the company (full-month charge that anchors the monthly billing day).
     */
    is_first_seat: boolean;
    /**
     * Projected total seat quantity (current + new) of the joint monthly cost after activation, or null on reason branches.
     */
    recurring_quantity: number | null;
    /**
     * Base (without VAT) of the projected joint monthly cost, in cents, or null.
     */
    recurring_base_cents: number | null;
    /**
     * Projected joint monthly cost with VAT, in cents; null when VAT is not calculable.
     */
    recurring_total_cents: number | null;
    /**
     * true when the seat WILL actually be billed: the very same predicate the hiring/reactivation gate uses (live paid plan, company not in sandbox) and the same field `GET /employee-seats` exposes. When false the operation never charges (enterprise by contract, trial, sandbox or live mode off) even though `amount` is computed — do not present it as a payment, and do not ask for confirmation of a charge that will not happen. Independent of the 0-amount branches: it can be true together with `already_covered` (the plan does bill seats, but THIS operation is free).
     */
    seats_billable: boolean;
};

/**
 * Error
 */
export type Error = {
    error: {
        /**
         * Machine-readable category of the error. Versioned by `Factuarea-Version`: from `2026-09-01` onwards the payment gate codes `payment_method_required`, `seat_charge_failed`, `gestoria_plan_required`, `employee_seat_payment_method_required` and `employee_seat_charge_failed` are served as `payment_required_error`; requests pinned to an earlier version keep receiving `invalid_request_error` for those five. `error.code` and `error.subcode` never change — branch on `code` if you want version-independent behaviour.
         */
        type: 'api_error' | 'authentication_error' | 'authorization_error' | 'conflict_error' | 'idempotency_error' | 'invalid_request_error' | 'not_found_error' | 'payment_required_error' | 'permission_error' | 'rate_limit_error' | 'service_unavailable_error';
        /**
         * Stable error code, e.g. missing_api_key, insufficient_scope, parameter_invalid, invalid_status_transition. Full reference of every code grouped by bounded context: https://docs.factuarea.com/guides/errors/all.
         */
        code: string;
        /**
         * Sub-code detailing the subtype within `code`. Present only on some errors, and only where `code` alone is ambiguous: on 409 duplication conflicts it pins the duplicate key (`code=resource_already_exists`, `subcode=tax_id_already_exists`), and on 402 payment errors it pins which gate rejected the call (`code=seat_charge_failed`, `subcode=seat_charge_failed`; `code=addon_required`, `subcode=webhooks_addon_required`). Like `code`, it is stable and invariant across locales and API versions.
         */
        subcode?: string | null;
        /**
         * Human-readable description in Spanish.
         */
        message: string;
        /**
         * Field that caused the error (for parameter_invalid and similar invalid_request_error codes). On multi-field validation errors it points to the FIRST failed field; the full set lives in `errors[]`.
         */
        param?: string | null;
        /**
         * Present on 422 validation errors: ALL failed fields, one item per field (not only the first). Each item carries `param`/`code`/`message` plus the optional hints `expected_format`/`allowed_values`. Additive and backward-compatible — `error.param`/`error.message` still mirror the first failed field.
         */
        errors?: Array<{
            /**
             * Name of the failed field.
             */
            param: string;
            /**
             * Stable machine-readable code for this field, derived from the failed validation rule (e.g. parameter_missing, parameter_invalid_format, parameter_invalid_enum).
             */
            code: string;
            /**
             * Human-readable description of the field error. Localized (es/en/ca) when its `code` belongs to the stable catalog.
             */
            message: string;
            /**
             * Expected format hint (e.g. `YYYY-MM-DD`, `uuid`, `email`, `url`). Only present when the failure is a format error.
             */
            expected_format?: string;
            /**
             * Legal values of the enum. Only present when the failure is an enum/`in` error.
             */
            allowed_values?: Array<string>;
        }>;
        /**
         * Structured details about the error, present only on some errors and with a shape that depends on the case. On 409 duplication conflicts (subcodes `tax_id_already_exists`, `external_id_already_exists`, `sku_already_exists`) it carries `existing_resource_id`, the UUID of the resource that already exists. On 402 `payment_required_error` responses caused by a missing payment method it carries `payment_setup_url`, the Billing Portal link that unblocks the operation. On the 422 subcodes raised inside the domain it carries the hint of that case: `allowed_values` (rejected value outside a closed catalog), `offending_field` (field a disbursement line may not carry) or `expected` + `received` (line total checksum mismatch).
         */
        details?: {
            /**
             * UUID of the pre-existing resource that triggered the conflict. Resolvable with a `GET /v1/{resource}/{id}` without an extra `find_by_*` call. Only present on 409 duplication conflicts.
             */
            existing_resource_id?: string;
            /**
             * Billing Portal URL where the payment method can be set up. Only present on 402 errors caused by a missing payment method (`payment_method_required`, `employee_seat_payment_method_required`); once the payment method is on file, retrying the same call succeeds. Absent on the other 402 codes (declined charge, plan or add-on required).
             */
            payment_setup_url?: string;
            /**
             * Legal values of the closed catalog the rejected value does not belong to. Present on the 422 subcodes that validate against a catalog inside the domain (`line_type_invalid`, `correction_code_illegal_for_original`). Note that a 422 raised by request validation reports the same hint per field in `error.errors[].allowed_values` instead.
             */
            allowed_values?: Array<string>;
            /**
             * Name of the line field that made the operation illegal. Present on 422 `suplido_line_cannot_carry_taxes`: a disbursement line (`line_type: "SUPLIDO"`) may not carry VAT, withholding, surcharge, discount, regime key, exemption cause or product, and this names the one that was sent.
             */
            offending_field?: string;
            /**
             * Amount this API computed for the line. Present on 422 `line_total_checksum_mismatch`, together with `received`, so the rounding mismatch with your own ERP can be located without guessing.
             */
            expected?: number;
            /**
             * Amount sent in `lines[].line_total`, which differs from `expected` by more than one cent. Present on 422 `line_total_checksum_mismatch`.
             */
            received?: number;
        };
        /**
         * Link to error reference in docs.
         */
        doc_url?: string | null;
        /**
         * Request ID for support/debugging.
         */
        request_id?: string | null;
    };
};

/**
 * Event
 *
 * A read-only record of something that happened in your account. The same object is delivered to your webhook endpoints.
 */
export type Event = {
    /**
     * Opaque identifier of the event, a UUID v7 (e.g. `01931b3e-7c4a-7f2e-9a8b-3c5d6e7f8a9b`). Consistent with the `id` field of every other v1 resource.
     */
    id: string;
    /**
     * Always `event`.
     */
    object: 'event';
    /**
     * Event type in `<category>.<action>` form (e.g. `invoice.paid`, `quote.approved`). See `GET /event-catalog` for the full list.
     */
    type: string;
    /**
     * UUID v7 of the resource that produced this event (e.g. the invoice for `invoice.paid`). `null` for events without backfill. Distinct from `id`, which identifies the event itself.
     */
    aggregate_id: string | null;
    /**
     * UUID v7 correlating this event end-to-end with the operation that produced it. `null` for events without a correlation context (e.g. born from scheduler sweeps). The key is always present.
     */
    correlation_id: string | null;
    /**
     * API version (date-based) the payload was serialized under, sealed at emission (e.g. `2026-05-22`). `null` only for legacy events emitted before versions were sealed.
     */
    api_version: string | null;
    /**
     * `true` for events generated in production (live keys, `fact_live_`); `false` for events generated in test mode (sandbox company, test keys `fact_test_`).
     */
    livemode: boolean;
    /**
     * `true` when the event is a test delivery triggered from the dashboard; `false` for real events. Orthogonal to `livemode`, which reflects the key environment (live vs sandbox): a test delivery may be issued in either, so e.g. `livemode: true, test: true` is valid.
     */
    test: boolean;
    data: EventData;
    /**
     * Unix timestamp (seconds) of when the event was created.
     */
    created: number;
};

/**
 * EventCatalogEntry
 *
 * A single event type available for webhook subscriptions. The full catalog is returned by `GET /v1/event-catalog`.
 */
export type EventCatalogEntry = {
    /**
     * Event identifier (e.g. `invoice.created`, `quote.approved`).
     */
    name: string;
    /**
     * High-level group derived from the prefix (`invoice`, `quote`, `client`, …).
     */
    category: string;
    /**
     * Human-readable description in Spanish.
     */
    description: string;
    /**
     * `available` if the event is emitted today; `coming_soon` if reserved for a future release.
     */
    status: 'available' | 'coming_soon';
};

