    /**
     * Completed recurrences (reached `max_occurrences`). Reported as `0` until the repository provides the dedicated count.
     */
    completed: number;
    /**
     * Recurrences whose next run is today.
     */
    due_today: number;
    /**
     * Recurrences whose next run falls in the current week.
     */
    due_this_week: number;
    /**
     * Invoices generated by recurrences during the current month.
     */
