    /**
     * Absence policy name.
     */
    name?: string | null;
    /**
     * Day allowance type: `limited` or `unlimited`.
     */
    allowance_type?: 'limited' | 'unlimited' | null;
    /**
     * Days allotted per year (positive; the domain requires a value when the allowance is `limited`).
     */
    allowance_days?: number | null;
