/**
 * VeriFactuActivity
 *
 * An event in the activity timeline of a VeriFactu record (creation, transmission attempts, AEAT acceptance/rejection).
 */
export type VeriFactuActivity = {
    object: 'verifactu_activity';
    /**
     * Tipo de evento de dominio (p. ej. `verifactu.record_created`, `verifactu.transmission_accepted`).
     */
    event_type: string;
    /**
     * Human-readable description of the event in Spanish.
     */
    description: string;
    /**
     * Event metadata. Internal identifiers (PKs), `huella` and certificate secrets are stripped; `*_uuid` values are preserved.
     */
    metadata: {
        [key: string]: unknown;
    };
    /**
     * Actor that originated the event. `{type:"user",...}` for an internal user, `{type:"api_key",...}` when performed via the public v1 API, or `null` when the event is system-generated (scheduler, periodic sweep) with no attributable actor.
     */
    performed_by: {
        /**
         * Type of actor that originated the event: `user` for a human in the internal app, `api_key` for an action performed through the public v1 API.
         */
        type: 'user' | 'api_key';
        /**
         * UUID (v7) of the actor: the user when `type=user`, or the API key when `type=api_key`.
         */
        id: string;
        /**
         * Actor name at the time of the event: the user name or the API key name. `null` if it could not be resolved.
         */
        name: string | null;
    } | null;
    /**
     * When the event occurred (ISO 8601).
     */
    created_at: string;
};

/**
 * VeriFactuConfig
 *
 * VeriFactu configuration of your company (mode, environment, enrollment). Returned by `GET /v1/verifactu/config` and `PUT /v1/verifactu/settings`. The certificate password is never exposed.
 */
export type VeriFactuConfig = {
    object: 'verifactu_config';
    /**
     * Indicates whether VeriFactu is enabled for the company.
     */
    enabled: boolean;
    /**
     * VeriFactu operation mode.
     */
    mode: string;
    /**
     * Indicates whether transmissions to AEAT are sent automatically.
     */
    auto_transmit: boolean;
    /**
     * Entorno AEAT (`sandbox` / `production`).
     */
    environment: string;
    /**
     * Notification emails for VeriFactu events.
     */
    notification_emails: Array<string>;
    /**
     * Date until which the mode change is locked, or `null` if not locked.
     */
    is_locked_until: string | null;
    /**
     * Indica si hay un certificado activo configurado.
     */
    has_active_certificate: boolean;
    /**
     * UUID (v7) of the active certificate, or `null` if there is none.
     */
    active_certificate_id: string | null;
    updated_at: string | null;
};

/**
 * VeriFactuEvent
 *
 * A VeriFactu SIF event (Art. 8.1.b): a transmission/retry/AEAT-response entry of the system. The hash chain is never exposed here.
 */
export type VeriFactuEvent = {
    /**
     * UUID (v7) of the event.
     */
    id: string;
    object: 'verifactu_event';
    /**
     * SIF event type.
     */
    event_type: string;
    /**
     * Non-PII descriptive data of the event (label, description, CSV, error code/message). Empty object `{}` when there is no data. Sanitized via MetadataSanitizer.
     */
    event_data: {
        [key: string]: unknown;
    };
    /**
     * AEAT status of the event.
     */
    status: string;
    /**
     * When the event was generated.
     */
    occurred_at: string;
    created_at: string;
    /**
     * Number of transmission attempts made.
     */
    retry_count: number;
    /**
     * Maximum number of retries configured.
     */
    max_retries: number;
};

/**
 * VeriFactuEventSummary
 *
 * Resumen agregado de los eventos del SIF de la empresa: total y desglose por tipo y por estado. Devuelto por `GET /v1/verifactu/events/summary`.
 */
export type VeriFactuEventSummary = {
    object: 'verifactu_event_summary';
    /**
     * Total de eventos registrados.
     */
    total_events: number;
    /**
     * Event count by type.
     */
    events_by_type: {
        [key: string]: number;
    };
    /**
     * Event count by AEAT status.
     */
    events_by_status: {
        [key: string]: number;
    };
    /**
     * Date of the last event, or `null` if there is none.
     */
    last_event_at: string | null;
};

/**
 * VeriFactuRecord
 *
 * A VeriFactu (Spanish AEAT SIF) record (alta/anulación) associated with an invoice. Includes the hash chain (`huella`), AEAT CSV and transmission status for reconciliation.
 */
export type VeriFactuRecord = {
    /**
     * UUID (v7) of the VeriFactu record.
     */
    id: string;
    object: 'verifactu_record';
    /**
     * Tipo de registro (`alta` / `anulacion`).
     */
    type: string;
    /**
     * AEAT invoice type (F1, F2, F3, R1-R5, …).
     */
    invoice_type: string;
    /**
     * Number of the associated invoice.
     */
    invoice_number: string;
    /**
     * Record date.
     */
    date: string;
    /**
     * Total amount of the associated invoice.
     */
    amount: string;
    /**
     * Transmission status (pending, submitted, accepted, rejected, error).
     */
    status: string;
    /**
     * Chained SHA-256 fingerprint of the record (VeriFactu fingerprint).
     */
    huella: string;
    /**
     * Submission identifier assigned by AEAT (column `aeat_submission_id`). `null` until AEAT returns it. Never the internal PK of the record.
     */
    aeat_submission_id: string | null;
    /**
     * Secure Verification Code (Código Seguro de Verificación) returned by AEAT on acceptance. `null` until AEAT assigns it.
     */
    aeat_csv: string | null;
    /**
     * Entorno AEAT (`sandbox` / `production`).
     */
    environment: string;
    /**
     * ISO 8601 date of the last transmission that reached AEAT. `null` in PENDING/REJECTED/ERROR states.
     */
    transmitted_at: string | null;
    /**
     * Whether the invoice is simplified (F2).
     */
    is_simplificada: boolean;
    /**
     * Whether it substitutes one or more simplified invoices (F3).
     */
    is_substitute_for_simplified: boolean;
    created_at: string;
};

/**
 * VeriFactuStats
 *
 * Resumen agregado de los registros VeriFactu de la empresa autenticada: conteos por estado y desglose por tipo. Devuelto por `GET /v1/verifactu/stats`.
 */
export type VeriFactuStats = {
    object: 'verifactu_stats';
    /**
     * Total de registros VeriFactu.
     */
    total_records: number;
    /**
     * Records pending transmission.
     */
    pending: number;
    /**
     * Records submitted to AEAT (without a final response yet).
     */
    submitted: number;
    /**
     * Records accepted by AEAT.
     */
    accepted: number;
    /**
     * Records rejected by AEAT.
     */
    rejected: number;
    /**
     * Registros en estado de error.
     */
    error: number;
    /**
     * Count by record type (registration/cancellation).
     */
    by_record_type: {
        [key: string]: number;
    };
    /**
     * Count by AEAT invoice type (F1, F2, F3, …).
     */
    by_invoice_type: {
        [key: string]: number;
    };
    /**
     * Date of the last transmission to AEAT, or `null` if there is none.
     */
    last_transmission_at: string | null;
};

/**
 * VerifyClientCensusRequest
 *
 * Public REST API v1 — POST /v1/clients/census-verification.
 *
 * Verifies a THIRD PARTY's name + tax_id pair (invoice recipient) against
 * the AEAT census (VNifV2). Max lengths mirror the Company BC value objects
 * consumed by the bridge (`TaxIdentifier` ≤ 20, `CompanyName` ≤ 100).
 */
export type VerifyClientCensusRequest = {
    /**
     * Spanish tax identifier (NIF/CIF/NIE) of the third party to check against the AEAT census
     */
    tax_id: string;
    /**
     * Name or business name of the third party (the name + tax ID pair is verified together)
     */
    name: string;
};

/**
 * VoidInvoiceRequest
 *
 * Public REST API v1 — POST /v1/invoices/{uuid}/void.
 *
 * Optional body: `reason` (string). If the API client does not send a
 * reason, a placeholder is persisted ("Anulada via API v1.").
 */
export type VoidInvoiceRequest = {
    reason?: string | null;
};

/**
 * Warehouse
 *
 * A warehouse: the physical place where stock lives, and the axis every movement, transfer and receipt of the ERP is booked against. It is a MASTER record, not a document: it has no number, no series and no lifecycle beyond being active or archived. Deleting one is publishing `DELETE` on it, and that ARCHIVES it — the row is kept, because three tables upstream hang their reference on it.
 */
export type Warehouse = {
    /**
     * Opaque identifier of the warehouse, a UUID v7. Every reference to it travels the same way: no internal numeric key is ever published.
     */
    id: string;
    /**
     * Always `warehouse`.
     */
    object: 'warehouse';
    /**
     * Code of the warehouse: the INTEGRATION key, unique per company among the living ones. It is the value `POST /warehouses/find-by-code` resolves, so a system that already knows its own warehouse by code does not have to store our identifier. Archiving a warehouse RELEASES its code, which can then be reused by a new one.
     */
    code: string;
    /**
     * Name of the warehouse, ready to display.
     */
    name: string;
    /**
     * Operational nature of the warehouse: `own` (a place of the company), `external` (a third party holding its goods), `store` (a point of sale) and `transit` (goods on their way between two of the above). It is a closed catalog and it does NOT change what the API lets you do with the warehouse: it classifies it.
     */
    type: 'own' | 'external' | 'store' | 'transit';
    /**
     * Lifecycle status: `active` (in operation) and `archived` (withdrawn). There is no un-archive operation in this API, which is why archiving is published as irreversible.
     */
    status: 'active' | 'archived';
    /**
     * Whether this is the DEFAULT warehouse of the company — the last link of the warehouse resolution chain of the whole ERP. At most one living warehouse carries it, and marking another one unmarks this one inside the same transaction. `GET /warehouses/default` reads it without paging the list.
     */
    is_default: boolean;
    /**
     * Address of the warehouse, broken down. It is the shape of the shared address value object of the contract, so it carries exactly these six fields and not the structured extras the client and supplier address publishes.
     */
    address: {
        /**
         * Street and number.
         */
        line1: string;
        /**
         * Second address line (building, industrial estate, bay), or `null`.
         */
        line2: string | null;
        /**
         * Town or city.
         */
        city: string;
        /**
         * Province.
         */
        province: string;
        /**
         * Postal code.
         */
        postal_code: string;
        /**
         * ISO 3166-1 alpha-2 country code.
         */
        country: string;
    };
    /**
     * Number of ACTIVE locations of the warehouse; the archived ones do not count. It is a COUNT and not an identifier: it is aggregated by the same query that serves the page, so listing warehouses never fires one query per row.
     */
    active_location_count: number;
};

/**
 * WarehouseAvailability
 *
 * What is available in ONE warehouse. It answers `where do I ship this from`, which the total cannot answer on its own.
 */
export type WarehouseAvailability = {
    /**
     * Always `warehouse_availability`.
     */
    object: 'warehouse_availability';
    /**
     * Opaque identifier of the warehouse. The name is not published here: it is resolved once against the warehouse master and kept, instead of travelling on every row of every page.
     */
    warehouse_id: string;
    /**
     * Available in that warehouse —physical minus committed— as a decimal string with four decimal places; it may be negative.
     */
    available: string;
};

/**
 * WarehouseLocation
 *
 * A location inside a warehouse: the aisle, the rack or the bay where the goods sit. It is a SUB-RESOURCE and never an autonomous one — it is not identified without its warehouse, and its operations consume the scope of the warehouse. The hierarchy admits ONE level: a location may hang from another, and a third level is rejected as a business rule.
 */
export type WarehouseLocation = {
    /**
     * Opaque identifier of the location, a UUID v7.
     */
    id: string;
    /**
     * Always `warehouse_location`.
     */
    object: 'warehouse_location';
    /**
     * Code of the location, unique per WAREHOUSE among the active ones — not per company: two warehouses may both have an `AISLE-A`.
     */
    code: string;
    /**
     * Name of the location, ready to display.
     */
    name: string;
    /**
     * Lifecycle status of the location. Archiving one with active children is rejected: what is inside is emptied first.
     */
    status: 'active' | 'archived';
    /**
     * Opaque identifier of the PARENT location. This key is ABSENT — not `null` — when the location is a root one, so a client checks for its presence and not for a null value. The internal surface of the application does publish the null, and that difference between the two contracts is deliberate.
     */
    parent_id?: string;
};

/**
 * WarehouseStatusItem
 *
 * A warehouse status from the closed catalog, with its label and what it allows. Returned by `GET /v1/companies/{company}/warehouses/statuses` as a flat list. The permissions are ANSWERED by the state machine of the domain, never copied into a hand-written list, so a status that changes what it allows changes it here too.
 */
export type WarehouseStatusItem = {
    /**
     * Always `warehouse_status_item`.
     */
    object: 'warehouse_status_item';
    /**
     * Status token. It is the identity of the status: a token of a closed catalog, not a row of any table.
     */
    value: 'active' | 'archived';
    /**
     * Label of the status in Spanish, ready to display.
     */
    label: string;
    /**
     * What the status admits over the warehouse. The catalog of THIS family publishes three capabilities, and not the ones of a document (`send`, `convert`): they would be `false` in every status and would only add vocabulary the warehouse does not speak.
     */
    permissions: {
        /**
         * Whether the status admits updating the warehouse. Only `active` does.
         */
        edit: boolean;
        /**
         * Whether the status admits ARCHIVING the warehouse, which is the effect of `DELETE`. Only `active` does, and only when the warehouse holds no active location and no live transfer.
         */
        archive: boolean;
        /**
         * Whether the status admits erasing the row. It is `false` in BOTH statuses, and that is the answer of the domain: this master is archived, never deleted, because the documents of the ERP hang their reference on it.
         */
        delete: boolean;
    };
};

/**
 * WebhookDelivery
 *
 * A single attempt to deliver an event to a webhook endpoint.
 */
export type WebhookDelivery = {
    id: string;
    object: 'webhook_delivery';
    webhook_endpoint_id: string;
    event_id: string;
    event_name: string;
    /**
     * Delivery status. `pending` (queued / in-flight), `delivered` (2xx received), `failed` (recoverable failure, will retry), `failed_permanently` (all attempts exhausted), `cancelled` (delivery aborted, terminal).
     */
    status: 'pending' | 'delivered' | 'failed' | 'failed_permanently' | 'cancelled';
    attempt: number;
    next_retry_at: string | null;
    /**
     * HTTP status from the endpoint.
     */
    response_status: number | null;
    response_body_truncated: string | null;
    duration_ms: number | null;
    /**
     * HMAC SHA-256 signature header value (`t=...,v1=...`) sent with this delivery, for debugging signature verification. `null` for deliveries created before signing or not yet attempted.
     */
    signature: string | null;
    /**
     * HTTP headers sent with this delivery attempt (debug). Empty object when no headers were captured.
     */
    request_headers: {
        [key: string]: string;
    };
    completed_at: string | null;
    created_at: string;
    payload: WebhookEventPayload;
};

/**
 * WebhookEndpoint
 *
 * An HTTPS endpoint that receives webhook events. The secret is never exposed in this representation.
 */
export type WebhookEndpoint = {
    id: string;
    object: 'webhook_endpoint';
    /**
     * HTTPS callback URL.
     */
    url: string;
    description: string | null;
    /**
     * List of event types this endpoint subscribes to.
     */
    enabled_events: Array<string>;
    /**
     * enabled, disabled, or paused.
     */
    status: string;
    /**
     * List of allowed source IPs.
     */
    ip_allowlist: Array<string> | null;
    delivery_success_rate_24h: number | null;
    last_delivery_at: string | null;
    last_failure_at: string | null;
    previous_secret_valid_until: string | null;
    created_at: string;
    updated_at: string;
    /**
     * API version (date-based, e.g. `2026-05-01`) pinned for the payloads delivered to this endpoint. `null` means the account default applies.
     */
    api_version: string | null;
    metadata: Metadata;
    custom_headers: CustomHeaders;
    /**
     * HTTP request timeout in seconds applied when delivering to this endpoint (1–30). `null` means the system default applies.
     */
    timeout_seconds: number | null;
    /**
     * Timestamp since which the endpoint is considered degraded (sustained delivery failures). `null` when healthy.
     */
    degraded_since: string | null;
};

/**
 * WebhookEndpointWithSecret
 *
 * A WebhookEndpoint returned once at creation or after secret rotation. Includes the plain-text signing secret.
 */
export type WebhookEndpointWithSecret = {
    id: string;
    object: 'webhook_endpoint';
    /**
     * HTTPS callback URL.
     */
    url: string;
    description: string | null;
    /**
     * List of event types this endpoint subscribes to.
     */
    enabled_events: Array<string>;
    /**
     * enabled, disabled, or paused.
     */
    status: string;
    /**
     * List of allowed source IPs.
     */
    ip_allowlist: Array<string> | null;
    delivery_success_rate_24h: number | null;
    last_delivery_at: string | null;
    last_failure_at: string | null;
    previous_secret_valid_until: string | null;
    created_at: string;
    updated_at: string;
    /**
     * API version (date-based, e.g. `2026-05-01`) pinned for the payloads delivered to this endpoint. `null` means the account default applies.
     */
    api_version: string | null;
    metadata: Metadata;
    custom_headers: CustomHeaders;
    /**
     * HTTP request timeout in seconds applied when delivering to this endpoint (1–30). `null` means the system default applies.
     */
    timeout_seconds: number | null;
    /**
     * Timestamp since which the endpoint is considered degraded (sustained delivery failures). `null` when healthy.
     */
    degraded_since: string | null;
    /**
     * Signing secret. Returned only at creation or after rotation.
     */
    secret: string;
};

